// ─── Language Switcher Component (Clean Top Flow) ───────────────────────────
function LanguageSwitcher() {
  const { lang, setLang, dir } = useRoadshowLang();
  const langs: { code: RoadshowLang; label: string }[] = dir === 'rtl'
    ? [{ code: 'fa', label: 'فارسی' }, { code: 'zh', label: '中文' }, { code: 'en', label: 'EN' }]
    : [{ code: 'en', label: 'EN' }, { code: 'zh', label: '中文' }, { code: 'fa', label: 'فارسی' }];

  return (
    <div style={{
      display: 'flex',
      justifyContent: dir === 'rtl' ? 'flex-start' : 'flex-end',
      width: '100%',
      marginBottom: '6px',
      gap: '5px',
      position: 'relative',
      zIndex: 10,
    }}>
      {langs.map(({ code, label }) => (
        <button
          key={code}
          onClick={() => setLang(code)}
          style={{
            background: lang === code ? 'linear-gradient(135deg, #FFF1D0 0%, #E0C996 100%)' : 'rgba(1, 3, 20, 0.65)',
            color: lang === code ? '#010314' : '#ffffff',
            border: `1px solid ${lang === code ? '#FFF1D0' : 'rgba(224, 201, 150, 0.4)'}`,
            fontFamily: "'Uxum Grotesque Medium', sans-serif",
            fontSize: '10.5px',
            padding: '4px 9px',
            borderRadius: '0px',
            cursor: 'pointer',
            letterSpacing: '0.08em',
            fontWeight: 600,
            textTransform: 'uppercase',
            transition: 'all 0.25s ease',
            backdropFilter: 'blur(8px)',
            WebkitBackdropFilter: 'blur(8px)',
          }}
          aria-pressed={lang === code}
        >
          {label}
        </button>
      ))}
    </div>
  );
}

