// ─── Registration Form Section (Pure VIP Pass RSVP Form) ───────────────────
function RegistrationForm() {
  const { lang, dir } = useRoadshowLang();
  const c = copy[lang].form;
  const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');
  const [fields, setFields] = useState({ firstName: '', lastName: '', mobile: '', email: '' });
  const baseInputId = useId();

  const getWhatsAppUrl = () => {
    const name = `${fields.firstName} ${fields.lastName}`.trim() || 'Valued Guest';
    const text = `Hello Team,\n\n${name} has registered for the Australian Roadshow 2026!\n\n📋 Registration Details:\n• Name: ${name}\n• Phone: ${fields.mobile}\n• Email: ${fields.email}\n• Event: WeNest Australian Roadshow 2026 (Melbourne)\n\nThank you!`;
    return `https://wa.me/971541511512?text=${encodeURIComponent(text)}`;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validate Phone Number Length & Format
    const phoneParts = fields.mobile.split(' ');
    const code = phoneParts[0]?.startsWith('+') ? phoneParts[0] : '+61';
    const num = phoneParts.slice(1).join('') || fields.mobile;
    const phoneVal = validatePhone(code, num);

    if (!phoneVal.isValid) {
      alert(phoneVal.errorReason || 'Please enter a valid mobile phone number.');
      return;
    }

    setStatus('submitting');

    // Trigger Google Ads & Meta Ads Conversion Tracking INSTANTLY on click of Confirm Reservation
    const eventId = trackEventConversion({
      eventName: 'WeNest Australian Roadshow 2026',
      eventLocation: 'Melbourne',
      formType: 'roadshow_landing',
      userEmail: fields.email,
      userPhone: fields.mobile,
      userName: `${fields.firstName} ${fields.lastName}`.trim(),
      customGoogleAdsLabel: 'AW-18364005209/-BYlCPTs198cEN6ok4FE',
    });

    const isDemo = isDemoContact({
      email: fields.email,
      firstName: fields.firstName,
      lastName: fields.lastName,
      phone: fields.mobile,
    });

    const utm = getStoredUtmParams();
    const waUrl = getWhatsAppUrl();

    if (!isDemo) {
      // 1. Dispatch background email notification to admin team with full UTM attribution & Meta CAPI deduplication
      const emailPayload = {
        firstName: fields.firstName,
        lastName: fields.lastName,
        email: fields.email,
        phone: fields.mobile,
        project: 'WeNest Australian Roadshow 2026 Registration',
        utm,
        eventId,
        formType: 'roadshow_landing',
      };
      fetch('/send-mail.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(emailPayload),
      }).catch(() => {});
      fetch('/api/send-mail', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(emailPayload),
      }).catch(() => {});

      // 2. Submit to HubSpot CRM (Enriched with tracking attribution & specific ad fields)
      try {
        const hutk = getHubspotCookie();
        const hsFields = [
          { name: 'firstname', value: fields.firstName },
          { name: 'lastname', value: fields.lastName },
          { name: 'phone', value: fields.mobile },
          { name: 'email', value: fields.email },
          { name: 'submission_type', value: 'Event Registration' },
          { name: 'event_name', value: 'WeNest Australian Roadshow 2026' },
        ];

        if (utm.utm_source) hsFields.push({ name: 'utm_source', value: utm.utm_source });
        if (utm.utm_medium) hsFields.push({ name: 'utm_medium', value: utm.utm_medium });
        if (utm.utm_campaign) hsFields.push({ name: 'utm_campaign', value: utm.utm_campaign });
        if (utm.utm_content) hsFields.push({ name: 'utm_content', value: utm.utm_content });
        if (utm.utm_term) hsFields.push({ name: 'utm_term', value: utm.utm_term });

        await fetch(REGISTRATION_FORM_URL, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            fields: hsFields,
            context: {
              hutk: hutk || undefined,
              pageUri: typeof window !== 'undefined' ? window.location.href : 'https://www.wenestre.com/roadshow/australian-roadshow-2026',
              pageName: 'Melbourne Roadshow 2026 (Event Registration)',
              ...(utm.gclid ? { gclid: utm.gclid } : {}),
            },
            legalConsentOptions: { consent: { consentToProcess: true, text: c.disclaimer } },
          }),
        });
      } catch { /* proceed to success */ }
    } else {
      console.log('[Demo Contact Detected] Bypassing Email & HubSpot CRM for test submission.');
    }

    setStatus('success');

    // 4. Auto-launch prefilled WhatsApp notification and redirect to Thank You page
    try {
      window.open(waUrl, '_blank');
      localStorage.setItem('wenest_roadshow_registered', '1');
    } catch { /* ignore popup blocker */ }

    setTimeout(() => {
      if (typeof window !== 'undefined') {
        window.location.href = '/roadshow/australian-roadshow-2026/thank-you?type=roadshow';
      }
    }, 1500);
  };

  const labelStyle: React.CSSProperties = {
    fontFamily: "'Uxum Grotesque Medium', sans-serif",
    fontSize: '11px',
    color: GOLD_ACCENT,
    textTransform: 'uppercase',
    letterSpacing: '2px',
    marginBottom: '8px',
    display: 'block',
    fontWeight: 600,
  };

  return (
    <section id="registration-form" style={{ margin: '0 auto', maxWidth: '640px', direction: dir }}>
      <div style={{
        backgroundColor: 'rgba(1, 3, 20, 0.85)',
        border: '1px solid rgba(224, 201, 150, 0.35)',
        padding: 'clamp(14px, 2vw, 24px) clamp(12px, 2vw, 20px)',
        backdropFilter: 'blur(16px)',
        boxShadow: '0 20px 60px rgba(0, 0, 0, 0.8)',
        borderRadius: '2px',
        textAlign: 'left',
      }}>
        <div className="invitation-agenda-title" style={{ marginBottom: '10px', fontSize: '10.5px', textAlign: 'center' }}>
          {c.heading}
        </div>

        {status === 'success' ? (
          <div style={{ textAlign: 'center', padding: '28px 16px' }}>
            <span style={{ fontSize: '52px', color: GOLD_ACCENT, display: 'block', marginBottom: '18px' }}>✓</span>
            <h3 style={{ fontFamily: "'Cormorant Garamond', 'Times New Roman', serif", fontSize: '32px', color: '#ffffff', marginBottom: '14px' }}>
              Invitation Confirmed
            </h3>
            <p style={{ fontFamily: "'Neue Montreal Regular', sans-serif", fontSize: '16.5px', color: GRAY_BODY, lineHeight: 1.75, marginBottom: '32px' }}>
              {c.success}
            </p>
            <a
              href={getWhatsAppUrl()}
              target="_blank"
              rel="noopener noreferrer"
              className="invitation-cta-btn"
              style={{ textDecoration: 'none', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: '10px' }}
            >
              <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.888-.788-1.489-1.761-1.662-2.06-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.095 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.577-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z" />
              </svg>
              <span>{lang === 'fa' ? 'تماس با تیم' : lang === 'zh' ? '联系团队' : 'Contact Team'}</span>
            </a>
          </div>
        ) : (
          <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '10px' }}>
              <div>
                <label htmlFor={`${baseInputId}-fn`} style={labelStyle}>{c.firstName}</label>
                <input
                  id={`${baseInputId}-fn`}
                  type="text"
                  required
                  value={fields.firstName}
                  onChange={e => setFields(p => ({ ...p, firstName: e.target.value }))}
                  className="invitation-input"
                  style={{ padding: '8px 12px', height: '36px', fontSize: '13px' }}
                  dir={dir}
                />
              </div>
              <div>
                <label htmlFor={`${baseInputId}-ln`} style={labelStyle}>{c.lastName}</label>
                <input
                  id={`${baseInputId}-ln`}
                  type="text"
                  required
                  value={fields.lastName}
                  onChange={e => setFields(p => ({ ...p, lastName: e.target.value }))}
                  className="invitation-input"
                  style={{ padding: '8px 12px', height: '36px', fontSize: '13px' }}
                  dir={dir}
                />
              </div>
            </div>

            <div>
              <label htmlFor={`${baseInputId}-mob`} style={labelStyle}>{c.mobile}</label>
              <PhoneInputWithCountry
                id={`${baseInputId}-mob`}
                value={fields.mobile}
                onChange={fullNumber => setFields(p => ({ ...p, mobile: fullNumber }))}
                inputClassName="invitation-input"
                inputStyle={{ padding: '8px 12px', height: '36px', fontSize: '13px' }}
                placeholder="412 345 678"
                required
                theme="dark"
              />
            </div>

            <div>
              <label htmlFor={`${baseInputId}-email`} style={labelStyle}>{c.email}</label>
              <input
                id={`${baseInputId}-email`}
                type="email"
                required
                value={fields.email}
                onChange={e => setFields(p => ({ ...p, email: e.target.value }))}
                className="invitation-input"
                style={{ padding: '8px 12px', height: '36px', fontSize: '13px' }}
                dir="ltr"
              />
            </div>

            <button
              type="submit"
              disabled={status === 'submitting'}
              className="invitation-cta-btn"
              style={{ width: '100%', marginTop: '4px', padding: '11px 16px', fontSize: '11.5px', opacity: status === 'submitting' ? 0.7 : 1 }}
            >
              {status === 'submitting'
                ? (lang === 'fa' ? 'در حال ارسال...' : lang === 'zh' ? '提交中...' : 'Submitting Reservation...')
                : c.submit}
            </button>

            {status === 'error' && (
              <p style={{ fontFamily: "'Neue Montreal Regular', sans-serif", fontSize: '11.5px', color: '#E74C3C', margin: 0, textAlign: 'center' }}>
                {lang === 'fa' ? 'خطایی رخ داد. لطفاً دوباره امتحان کنید.'
                  : lang === 'zh' ? '出现错误，请重试。'
                  : 'Something went wrong. Please try again.'}
              </p>
            )}

            <p style={{ fontFamily: "'Neue Montreal Regular', sans-serif", fontSize: '10.5px', color: GRAY_BODY, lineHeight: 1.4, opacity: 0.75, textAlign: 'center', margin: 0 }}>
              {c.disclaimer}
            </p>
          </form>
        )}
      </div>
    </section>
  );
}

