'use client';

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';

export type RoadshowLang = 'en' | 'zh' | 'fa';

interface RoadshowLangContextValue {
  lang: RoadshowLang;
  setLang: (l: RoadshowLang) => void;
  dir: 'ltr' | 'rtl';
}

const STORAGE_KEY = 'wenest_roadshow_lang';

const RoadshowLangContext = createContext<RoadshowLangContextValue>({
  lang: 'en',
  setLang: () => {},
  dir: 'ltr',
});

function detectUrlLang(): RoadshowLang | null {
  if (typeof window === 'undefined') return null;
  
  try {
    // 1. Check URL query parameters ?lang=zh, ?lang=fa, ?lang=en, or ?l=zh
    const params = new URLSearchParams(window.location.search);
    const qLang = (params.get('lang') || params.get('l'))?.toLowerCase();
    if (qLang && ['en', 'zh', 'fa'].includes(qLang)) {
      return qLang as RoadshowLang;
    }

    // 2. Check URL hash #zh, #fa, #en
    const hash = window.location.hash.replace('#', '').toLowerCase();
    if (['en', 'zh', 'fa'].includes(hash)) {
      return hash as RoadshowLang;
    }
  } catch { /* ignore */ }

  return null;
}

function detectBrowserLang(): RoadshowLang {
  if (typeof navigator === 'undefined') return 'en';
  const nav = navigator.language || '';
  if (nav.startsWith('zh')) return 'zh';
  if (nav.startsWith('fa') || nav.startsWith('per')) return 'fa';
  return 'en';
}

export function RoadshowLangProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<RoadshowLang>('en');

  useEffect(() => {
    // Priority: 1. URL parameter (?lang=zh) or Hash (#zh) -> 2. LocalStorage -> 3. Browser language
    const urlLang = detectUrlLang();
    if (urlLang) {
      setLangState(urlLang);
      try { localStorage.setItem(STORAGE_KEY, urlLang); } catch { /* ignore */ }
      return;
    }

    const stored = localStorage.getItem(STORAGE_KEY) as RoadshowLang | null;
    if (stored && ['en', 'zh', 'fa'].includes(stored)) {
      setLangState(stored);
    } else {
      setLangState(detectBrowserLang());
    }
  }, []);

  const setLang = useCallback((l: RoadshowLang) => {
    setLangState(l);
    try {
      localStorage.setItem(STORAGE_KEY, l);
      if (typeof window !== 'undefined') {
        const url = new URL(window.location.href);
        url.searchParams.set('lang', l);
        window.history.replaceState({}, '', url.toString());
      }
    } catch { /* ignore */ }
  }, []);

  const dir: 'ltr' | 'rtl' = lang === 'fa' ? 'rtl' : 'ltr';

  return (
    <RoadshowLangContext.Provider value={{ lang, setLang, dir }}>
      {children}
    </RoadshowLangContext.Provider>
  );
}

export function useRoadshowLang() {
  return useContext(RoadshowLangContext);
}
